SELECT DATE_FORMAT(s.opened_date, 'yyyy-MM') AS opened_month, ROUND(STDDEV(p.amount), 2) AS stddev_amount, ROUND((100 * SUM(CASE WHEN p.method = 'paypal' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_paypal FROM payments p INNER JOIN orders o ON p.order_id = o.id INNER JOIN stores s ON o.store_id = s.id WHERE s.sqft IS NULL GROUP BY DATE_FORMAT(s.opened_date, 'yyyy-MM')
